Object.assign(SNIP,{});PRESET_NOTES["l52"]={"Ví dụ: BFS từ đỉnh 1": "Đỉnh được tô theo thứ tự lớp: 1 (lớp 0), 2 và 3 (lớp 1), 4 và 5 (lớp 2), 6 (lớp 3), 7 (lớp 4). Cạnh đậm là cạnh u → v lúc v được phát hiện: chúng tạo thành cây BFS, đường trên cây từ 1 tới mỗi đỉnh là một đường ngắn nhất.", "Ví dụ: In đường đi ngắn nhất": "Từ 7 đi ngược: cha[7] = 6, cha[6] = 4, cha[4] = 2, cha[2] = 1. Đảo lại được 1 2 4 6 7, dài 4 cạnh.", "Ví dụ: BFS trên lưới": "Bảng d loang ra từ S theo từng lớp. Tới T cần 5 bước. Ô tường giữ −1. Hai mảng dx, dy thay cho việc dựng danh sách kề.", "Ví dụ: BFS từ nhiều nguồn": "Cả hai trạm vào hàng đợi trước với khoảng cách 0. Mỗi nhà nhận khoảng cách tới trạm gần nhất: 1 0 1 2 3 2 1 0 1. Chạy BFS riêng từ từng trạm rồi lấy min cũng ra kết quả này nhưng tốn gấp k lần.", "Lỗi: đánh dấu khi lấy ra thay vì khi đưa vào": "Kết quả vẫn đúng nhưng hàng đợi nhận 16 lượt đẩy cho 6 đỉnh: một đỉnh bị đẩy lại từ mỗi hàng xóm đã thăm trước nó. Với đồ thị dày, số lượt đẩy tiến tới O(m) thay vì n và bộ nhớ hàng đợi phình to. Đánh dấu ngay lúc đẩy vào thì mỗi đỉnh vào đúng một lần."};EX_HINTS["l52"]=[["dist khởi tạo -1 (chưa thăm); dist[1] = 0 và đưa 1 vào hàng đợi.", "Lấy u ra, với mỗi v kề u chưa thăm: dist[v] = dist[u] + 1, đưa v vào hàng đợi.", "Có thể có khuyên (u = v) và cạnh lặp: BFS xử lý được, không cần làm gì thêm."], ["Mỗi ô là một đỉnh; hàng đợi chứa cặp (hàng, cột). Tìm vị trí S và T trước.", "Với mỗi ô lấy ra, thử 4 hướng bằng dx, dy; bỏ qua ô ra ngoài lưới, ô tường, ô đã thăm.", "Kiểm tra biên trước rồi mới đọc g[nx][ny], kẻo truy cập ngoài mảng."], ["Truy vết bằng mảng cha từ s chỉ cho một đường bất kỳ. Muốn nhỏ nhất theo thứ tự từ điển phải chọn tốt từ đỉnh ĐẦU (ý của bài 50).", "BFS từ t để có d[v] = khoảng cách từ v tới t. Từ s, đỉnh v kề u nằm trên một đường ngắn nhất khi d[v] = d[u] − 1.", "Mỗi bước chọn v nhỏ nhất thỏa điều kiện. Tổng chi phí vẫn O(n + m)."]];
/* ===================== BÀI 52 · BFS và đường đi ngắn nhất không trọng số ===================== */
/* Bài 52 · BFS và đường đi ngắn nhất không trọng số
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR52=[{label:"Ví dụ: BFS từ đỉnh 1",input:"7 8\n1 2\n1 3\n2 4\n3 4\n3 5\n4 6\n5 6\n6 7\n",code:"#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    vector<int> dist(n + 1, -1), cha(n + 1, 0);\n    queue<int> q;\n    dist[1] = 0;\n    q.push(1);\n    while (!q.empty()) {\n        int u = q.front();\n        q.pop();\n        for (int v : adj[u]) {\n            if (dist[v] == -1) {           // chưa thăm: đánh dấu NGAY khi đưa vào\n                dist[v] = dist[u] + 1;\n                cha[v] = u;\n                q.push(v);\n            }\n        }\n    }\n\n    for (int u = 1; u <= n; u++) cout << dist[u] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",adj:"adj",base:1,n:"n",lab:"dist",par:"cha",cur:["u","v"]},{type:"cont",of:"q"}],py:{code:"from collections import deque\n\nn, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]\nfor _ in range(m):\n    u, v = map(int, input().split())\n    adj[u].append(v)\n    adj[v].append(u)\ndist = [-1] * (n + 1)\ncha = [0] * (n + 1)\nq = deque([1])\ndist[1] = 0\nwhile q:\n    u = q.popleft()\n    for v in adj[u]:\n        if dist[v] == -1:              # chưa thăm: đánh dấu NGAY khi đưa vào\n            dist[v] = dist[u] + 1\n            cha[v] = u\n            q.append(v)\nprint(*dist[1:])"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        var adj = new List<int>[n + 1];\n        for (int u = 0; u <= n; u++) adj[u] = new List<int>();\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            adj[e[1]].Add(e[0]);\n        }\n        int[] dist = new int[n + 1], cha = new int[n + 1];\n        Array.Fill(dist, -1);\n        var q = new Queue<int>();\n        dist[1] = 0;\n        q.Enqueue(1);\n        while (q.Count > 0)\n        {\n            int u = q.Dequeue();\n            foreach (int v in adj[u])\n            {\n                if (dist[v] == -1)             // chưa thăm: đánh dấu NGAY khi đưa vào\n                {\n                    dist[v] = dist[u] + 1;\n                    cha[v] = u;\n                    q.Enqueue(v);\n                }\n            }\n        }\n        var sb = new StringBuilder();\n        for (int u = 1; u <= n; u++) sb.Append(dist[u]).Append(' ');\n        Console.WriteLine(sb.ToString());\n    }\n}"}},{label:"Ví dụ: In đường đi ngắn nhất",input:"7 8\n1 2\n1 3\n2 4\n3 4\n3 5\n4 6\n5 6\n6 7\n",code:"#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n#include <algorithm>\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    vector<int> dist(n + 1, -1), cha(n + 1, 0);\n    queue<int> q;\n    dist[1] = 0;\n    q.push(1);\n    while (!q.empty()) {\n        int u = q.front();\n        q.pop();\n        for (int v : adj[u]) {\n            if (dist[v] == -1) {           // chưa thăm: đánh dấu NGAY khi đưa vào\n                dist[v] = dist[u] + 1;\n                cha[v] = u;\n                q.push(v);\n            }\n        }\n    }\n\n    int t = 7;\n    vector<int> duong;\n    for (int x = t; x != 1; x = cha[x]) duong.push_back(x);   // đi ngược theo cha\n    duong.push_back(1);\n    reverse(duong.begin(), duong.end());\n    cout << dist[t] << \":\";\n    for (int x : duong) cout << \" \" << x;\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",adj:"adj",base:1,n:"n",lab:"dist",par:"cha",cur:["x"]},{type:"cells",of:"cha",ptr:["x"]}],py:{code:"from collections import deque\n\nn, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]\nfor _ in range(m):\n    u, v = map(int, input().split())\n    adj[u].append(v)\n    adj[v].append(u)\ndist = [-1] * (n + 1)\ncha = [0] * (n + 1)\nq = deque([1])\ndist[1] = 0\nwhile q:\n    u = q.popleft()\n    for v in adj[u]:\n        if dist[v] == -1:              # chưa thăm: đánh dấu NGAY khi đưa vào\n            dist[v] = dist[u] + 1\n            cha[v] = u\n            q.append(v)\nt = 7\nduong = []\nx = t\nwhile x != 1:                          # đi ngược theo cha\n    duong.append(x)\n    x = cha[x]\nduong.append(1)\nduong.reverse()\nprint(str(dist[t]) + \":\", *duong)"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        var adj = new List<int>[n + 1];\n        for (int u = 0; u <= n; u++) adj[u] = new List<int>();\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            adj[e[1]].Add(e[0]);\n        }\n        int[] dist = new int[n + 1], cha = new int[n + 1];\n        Array.Fill(dist, -1);\n        var q = new Queue<int>();\n        dist[1] = 0;\n        q.Enqueue(1);\n        while (q.Count > 0)\n        {\n            int u = q.Dequeue();\n            foreach (int v in adj[u])\n            {\n                if (dist[v] == -1)             // chưa thăm: đánh dấu NGAY khi đưa vào\n                {\n                    dist[v] = dist[u] + 1;\n                    cha[v] = u;\n                    q.Enqueue(v);\n                }\n            }\n        }\n        int t = 7;\n        var duong = new List<int>();\n        for (int x = t; x != 1; x = cha[x]) duong.Add(x);   // đi ngược theo cha\n        duong.Add(1);\n        duong.Reverse();\n        Console.WriteLine(dist[t] + \": \" + string.Join(\" \", duong));\n    }\n}",viz:[{type:"graph",adj:"adj",base:1,n:"n",lab:"dist",par:"cha"},{type:"cells",of:"cha"}]}},{label:"Ví dụ: BFS trên lưới",input:"",code:"#include <iostream>\n#include <vector>\n#include <queue>\n#include <string>\nusing namespace std;\n\nint main() {\n    vector<string> g = {\"S.#.\",\n                        \"..#.\",\n                        \"....\",\n                        \"#.T.\"};\n    int R = 4, C = 4;\n    int d[4][4];\n    for (int i = 0; i < R; i++) for (int j = 0; j < C; j++) d[i][j] = -1;\n    int dx[4] = {-1, 1, 0, 0}, dy[4] = {0, 0, -1, 1};   // lên, xuống, trái, phải\n    queue<pair<int,int>> q;\n    d[0][0] = 0;\n    q.push({0, 0});\n    while (!q.empty()) {\n        int x = q.front().first, y = q.front().second;\n        q.pop();\n        for (int k = 0; k < 4; k++) {\n            int nx = x + dx[k], ny = y + dy[k];\n            if (nx < 0 || nx >= R || ny < 0 || ny >= C) continue;   // ra ngoài lưới\n            if (g[nx][ny] == '#' || d[nx][ny] != -1) continue;      // tường hoặc đã thăm\n            d[nx][ny] = d[x][y] + 1;\n            q.push({nx, ny});\n        }\n    }\n    cout << d[3][2] << \"\\n\";\n    return 0;\n}",viz:[{type:"grid",of:"d"}],py:{code:"from collections import deque\n\ng = [\"S.#.\",\n     \"..#.\",\n     \"....\",\n     \"#.T.\"]\nR, C = 4, 4\nd = [[-1] * C for _ in range(R)]\nhuong = [(-1, 0), (1, 0), (0, -1), (0, 1)]   # lên, xuống, trái, phải\nq = deque([(0, 0)])\nd[0][0] = 0\nwhile q:\n    x, y = q.popleft()\n    for dx, dy in huong:\n        nx, ny = x + dx, y + dy\n        if not (0 <= nx < R and 0 <= ny < C):  # ra ngoài lưới\n            continue\n        if g[nx][ny] == \"#\" or d[nx][ny] != -1:   # tường hoặc đã thăm\n            continue\n        d[nx][ny] = d[x][y] + 1\n        q.append((nx, ny))\nprint(d[3][2])"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] g = { \"S.#.\",\n                       \"..#.\",\n                       \"....\",\n                       \"#.T.\" };\n        int R = 4, C = 4;\n        int[][] d = new int[R][];\n        for (int i = 0; i < R; i++) { d[i] = new int[C]; Array.Fill(d[i], -1); }\n        int[] dx = { -1, 1, 0, 0 }, dy = { 0, 0, -1, 1 };   // lên, xuống, trái, phải\n        var q = new Queue<int>();              // ô (x, y) cất thành số x * C + y\n        d[0][0] = 0;\n        q.Enqueue(0);\n        while (q.Count > 0)\n        {\n            int o = q.Dequeue(), x = o / C, y = o % C;\n            for (int k = 0; k < 4; k++)\n            {\n                int nx = x + dx[k], ny = y + dy[k];\n                if (nx < 0 || nx >= R || ny < 0 || ny >= C) continue;   // ra ngoài lưới\n                if (g[nx][ny] == '#' || d[nx][ny] != -1) continue;      // tường hoặc đã thăm\n                d[nx][ny] = d[x][y] + 1;\n                q.Enqueue(nx * C + ny);\n            }\n        }\n        Console.WriteLine(d[3][2]);\n    }\n}"}},{label:"Ví dụ: BFS từ nhiều nguồn",input:"",code:"#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nint main() {\n    int n = 9;\n    vector<vector<int>> adj(n + 1);\n    int eu[8] = {1, 2, 3, 4, 5, 6, 7, 8};\n    int ev[8] = {2, 3, 4, 5, 6, 7, 8, 9};      // một con đường thẳng 1 - 2 - … - 9\n    for (int i = 0; i < 8; i++) { adj[eu[i]].push_back(ev[i]); adj[ev[i]].push_back(eu[i]); }\n    vector<int> dist(n + 1, -1);\n    queue<int> q;\n    int tram[2] = {2, 8};                      // hai trạm cứu hỏa\n    for (int k = 0; k < 2; k++) { dist[tram[k]] = 0; q.push(tram[k]); }\n    while (!q.empty()) {\n        int u = q.front();\n        q.pop();\n        for (int v : adj[u])\n            if (dist[v] == -1) { dist[v] = dist[u] + 1; q.push(v); }\n    }\n    for (int u = 1; u <= n; u++) cout << dist[u] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",adj:"adj",base:1,n:"n",lab:"dist",cur:["u","v"]},{type:"cont",of:"q"}],py:{code:"from collections import deque\n\nn = 9\nadj = [[] for _ in range(n + 1)]\nfor u in range(1, n):                  # một con đường thẳng 1 - 2 - … - 9\n    adj[u].append(u + 1)\n    adj[u + 1].append(u)\ndist = [-1] * (n + 1)\nq = deque()\nfor s in [2, 8]:                       # hai trạm cứu hỏa\n    dist[s] = 0\n    q.append(s)\nwhile q:\n    u = q.popleft()\n    for v in adj[u]:\n        if dist[v] == -1:\n            dist[v] = dist[u] + 1\n            q.append(v)\nprint(*dist[1:])"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 9;\n        var adj = new List<int>[n + 1];\n        for (int u = 0; u <= n; u++) adj[u] = new List<int>();\n        for (int u = 1; u < n; u++) { adj[u].Add(u + 1); adj[u + 1].Add(u); }   // con đường 1 - 2 - … - 9\n        int[] dist = new int[n + 1];\n        Array.Fill(dist, -1);\n        var q = new Queue<int>();\n        foreach (int s in new[] { 2, 8 }) { dist[s] = 0; q.Enqueue(s); }      // hai trạm cứu hỏa\n        while (q.Count > 0)\n        {\n            int u = q.Dequeue();\n            foreach (int v in adj[u])\n                if (dist[v] == -1) { dist[v] = dist[u] + 1; q.Enqueue(v); }\n        }\n        var sb = new StringBuilder();\n        for (int u = 1; u <= n; u++) sb.Append(dist[u]).Append(' ');\n        Console.WriteLine(sb.ToString());\n    }\n}"}},{label:"Lỗi: đánh dấu khi lấy ra thay vì khi đưa vào",input:"",code:"#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nint main() {\n    int n = 6;\n    vector<vector<int>> adj(n + 1);\n    for (int u = 1; u <= n; u++)               // đồ thị đầy đủ 6 đỉnh: mọi cặp đều kề\n        for (int v = 1; v <= n; v++)\n            if (u != v) adj[u].push_back(v);\n    vector<bool> tham(n + 1, false);\n    queue<int> q;\n    q.push(1);\n    int soLanDay = 1;\n    while (!q.empty()) {\n        int u = q.front();\n        q.pop();\n        if (tham[u]) continue;\n        tham[u] = true;                        // SAI: đánh dấu muộn\n        for (int v : adj[u])\n            if (!tham[v]) { q.push(v); soLanDay++; }\n    }\n    cout << soLanDay << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",adj:"adj",base:1,n:"n",mark:"tham",cur:["u"]},{type:"cont",of:"q"}],py:{code:"from collections import deque\n\nn = 6\nadj = [[v for v in range(1, n + 1) if v != u] for u in range(n + 1)]   # đồ thị đầy đủ\nadj[0] = []\ntham = [False] * (n + 1)\nq = deque([1])\nso_lan_day = 1\nwhile q:\n    u = q.popleft()\n    if tham[u]:\n        continue\n    tham[u] = True                     # SAI: đánh dấu muộn\n    for v in adj[u]:\n        if not tham[v]:\n            q.append(v)\n            so_lan_day += 1\nprint(so_lan_day)"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 6;\n        var adj = new List<int>[n + 1];\n        for (int u = 0; u <= n; u++)\n        {\n            adj[u] = new List<int>();\n            for (int v = 1; v <= n; v++) if (u >= 1 && u != v) adj[u].Add(v);   // đồ thị đầy đủ\n        }\n        bool[] tham = new bool[n + 1];\n        var q = new Queue<int>();\n        q.Enqueue(1);\n        int soLanDay = 1;\n        while (q.Count > 0)\n        {\n            int u = q.Dequeue();\n            if (tham[u]) continue;\n            tham[u] = true;                    // SAI: đánh dấu muộn\n            foreach (int v in adj[u])\n                if (!tham[v]) { q.Enqueue(v); soLanDay++; }\n        }\n        Console.WriteLine(soLanDay);\n    }\n}"}}];
const sim52=makeSim2(document.getElementById("sim-l52"),{id:"s52",presets:PR52});
makeEx2(document.getElementById("ex-l52"),sim52,[{t:"Khoảng cách từ trung tâm",d:"Đồ thị vô hướng n đỉnh, m cạnh, mọi cạnh dài 1 (1 ≤ n, m ≤ 2·10^5; m ≥ 1). Đầu vào: n m rồi m dòng u v. Đầu ra: một dòng n số, số thứ i là số cạnh ít nhất đi từ đỉnh 1 tới đỉnh i, hoặc -1 nếu không tới được.",tests:[{in:"7 8\n1 2\n1 3\n2 4\n3 4\n3 5\n4 6\n5 6\n6 7",out:"0 1 1 2 2 3 4"},{in:"3 1\n2 3",out:"0 -1 -1"},{in:"4 4\n1 2\n2 3\n3 4\n4 1",out:"0 1 2 1"},{in:"5 2\n1 1\n2 3",out:"0 -1 -1 -1 -1"},{in:"40 45\n18 4\n33 31\n24 27\n3 9\n11 27\n12 23\n29 1\n3 35\n25 29\n1 16\n5 11\n11 31\n15 18\n32 27\n8 3\n40 25\n6 37\n26 24\n35 9\n10 26\n34 12\n18 6\n21 12\n28 37\n28 39\n2 13\n1 14\n34 31\n30 9\n11 8\n12 6\n9 39\n14 20\n13 36\n37 28\n5 36\n11 14\n10 33\n15 37\n29 39\n10 16\n34 25\n34 13\n5 10\n3 40",out:"0 5 4 7 3 5 -1 3 3 2 2 4 4 1 5 1 -1 6 -1 2 5 -1 5 4 2 3 3 3 1 4 3 4 3 3 4 4 4 -1 2 3"}],start:"#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    vector<int> dist(n + 1, -1);\n    // BFS từ đỉnh 1\n    for (int u = 1; u <= n; u++) cout << dist[u] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",perf:{gen:n=>{const r=[];for(let i=n-1;i>=1;i--)r.push((i+1)+" "+i);return n+" "+(n-1)+"\n"+r.join("\n")},ns:[250,500,1000,2000],need:"n",limit:n=>80*n+300,why:"Cập nhật khoảng cách bằng cách duyệt đi duyệt lại mọi cạnh tới khi không đổi tốn O(n·m)."},py:{start:"from collections import deque\n\nn, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]\nfor _ in range(m):\n    u, v = map(int, input().split())\n    adj[u].append(v)\n    adj[v].append(u)\ndist = [-1] * (n + 1)\n# BFS từ đỉnh 1\nprint(*dist[1:])",hints:["dist khởi tạo -1 (chưa thăm); dist[1] = 0 và đưa 1 vào deque.","Lấy u ra bằng popleft(), với mỗi v kề u chưa thăm: dist[v] = dist[u] + 1, append(v).","Dùng deque, đừng dùng list.pop(0): mỗi lần pop(0) tốn O(n)."]},cs:{start:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        var adj = new List<int>[n + 1];\n        for (int u = 0; u <= n; u++) adj[u] = new List<int>();\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            adj[e[1]].Add(e[0]);\n        }\n        int[] dist = new int[n + 1];\n        Array.Fill(dist, -1);\n        // BFS từ đỉnh 1\n        var sb = new StringBuilder();\n        for (int u = 1; u <= n; u++) sb.Append(dist[u]).Append(' ');\n        Console.WriteLine(sb.ToString());\n    }\n}",hints:["dist khởi tạo -1 (Array.Fill); dist[1] = 0 và Enqueue(1).","Dequeue u, với mỗi v kề u chưa thăm: dist[v] = dist[u] + 1, Enqueue(v).","Có thể có khuyên (u = v) và cạnh lặp: BFS xử lý được, không cần làm gì thêm."]}},{t:"Thoát mê cung",d:"Mê cung R × C (1 ≤ R, C ≤ 1000): '.' là ô trống, '#' là tường, có đúng một ô 'S' (xuất phát) và một ô 'T' (lối ra). Mỗi bước đi sang một ô chung cạnh không phải tường. Đầu vào: R C rồi R dòng. Đầu ra: số bước ít nhất từ S tới T, hoặc -1 nếu không tới được.",tests:[{in:"4 4\nS.#.\n..#.\n....\n#.T.",out:"5"},{in:"1 2\nST",out:"1"},{in:"1 3\nS#T",out:"-1"},{in:"3 3\nS..\n##.\nT..",out:"6"},{in:"3 3\nS.#\n##.\n..T",out:"-1"},{in:"15 20\nS.##.#....#.#..#...#\n..#.....#....#.##..#\n.............#..#...\n#.....##.#..#.......\n...##...#..##..#..#.\n...#.......#........\n.........#..........\n#..##..##...###.....\n.....#.#........#...\n..##....#..#.....##.\n.....##....###......\n......#...#####...#.\n##...#...#.........#\n.#.#..#.#.#..##.#...\n.#..##..#..........T",out:"33"}],start:"#include <iostream>\n#include <vector>\n#include <queue>\n#include <string>\nusing namespace std;\n\nint main() {\n    int R, C;\n    cin >> R >> C;\n    vector<string> g(R);\n    for (int i = 0; i < R; i++) cin >> g[i];\n    vector<vector<int>> d(R, vector<int>(C, -1));\n    int dx[4] = {-1, 1, 0, 0}, dy[4] = {0, 0, -1, 1};\n    // tìm S, BFS trên lưới, in khoảng cách tới T\n    cout << -1 << \"\\n\";\n    return 0;\n}",perf:{gen:n=>{const C=Math.floor(n/2);const a="T"+".".repeat(C-1),b=".".repeat(C-1)+"S";return "2 "+C+"\n"+a+"\n"+b},ns:[250,500,1000,2000],need:"n",limit:n=>150*n+300,why:"Lặp lại việc cập nhật khoảng cách trên cả lưới tới khi không đổi tốn O((R·C)²)."},py:{start:"from collections import deque\n\nR, C = map(int, input().split())\ng = [input() for _ in range(R)]\nd = [[-1] * C for _ in range(R)]\n# tìm S, BFS trên lưới, in khoảng cách tới T\nprint(-1)",hints:["Mỗi ô là một đỉnh; deque chứa bộ (hàng, cột). Tìm vị trí S và T trước.","Với mỗi ô lấy ra, thử 4 hướng; bỏ qua ô ra ngoài lưới, ô tường, ô đã thăm.","Kiểm tra biên trước: với chỉ số âm, g[-1] trong Python không báo lỗi mà đọc hàng cuối!"]},cs:{start:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] rc = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int R = rc[0], C = rc[1];\n        string[] g = new string[R];\n        for (int i = 0; i < R; i++) g[i] = Console.ReadLine();\n        int[] dx = { -1, 1, 0, 0 }, dy = { 0, 0, -1, 1 };\n        // tìm S, BFS trên lưới (ô (x, y) cất thành x * C + y), in khoảng cách tới T\n        Console.WriteLine(-1);\n    }\n}",hints:["Mỗi ô là một đỉnh; cất ô (x, y) thành một số x · C + y để dùng Queue<int> và mảng một chiều.","Với mỗi ô lấy ra, thử 4 hướng; bỏ qua ô ra ngoài lưới, ô tường, ô đã thăm.","Kiểm tra biên trước rồi mới đọc g[nx][ny], kẻo IndexOutOfRangeException."]}},{t:"Chỉ đường qua ít trạm nhất",d:"Đồ thị vô hướng n đỉnh, m cạnh (2 ≤ n ≤ 10^5, 1 ≤ m ≤ 2·10^5) và hai đỉnh s ≠ t. Đầu vào: n m, m dòng u v, rồi dòng s t. Đầu ra: nếu không tới được in -1. Ngược lại dòng 1 là số cạnh ít nhất; dòng 2 là các đỉnh trên một đường ngắn nhất từ s tới t. Nếu có nhiều đường ngắn nhất, in đường nhỏ nhất theo thứ tự từ điển (so dãy đỉnh từ đầu).",tests:[{in:"7 8\n1 2\n1 3\n2 4\n3 4\n3 5\n4 6\n5 6\n6 7\n1 7",out:"4\n1 2 4 6 7"},{in:"4 2\n1 2\n3 4\n1 4",out:"-1"},{in:"4 3\n1 4\n1 2\n2 4\n1 4",out:"1\n1 4"},{in:"6 7\n1 3\n1 2\n2 6\n3 6\n1 4\n4 5\n5 6\n1 6",out:"2\n1 2 6"},{in:"30 45\n8 30\n9 6\n13 23\n26 14\n23 17\n30 7\n3 15\n10 6\n13 2\n3 7\n5 18\n26 21\n18 25\n21 13\n3 22\n28 30\n27 2\n7 18\n14 8\n27 24\n5 11\n30 12\n11 25\n30 22\n24 2\n19 16\n28 12\n4 5\n8 1\n8 16\n13 27\n6 8\n27 10\n21 7\n19 27\n12 7\n5 4\n27 21\n13 10\n3 17\n10 3\n1 16\n23 4\n4 11\n23 21\n1 30",out:"2\n1 8 30"}],start:"#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    int s, t;\n    cin >> s >> t;\n    // BFS từ t; rồi đi từ s, mỗi bước sang đỉnh kề NHỎ NHẤT có khoảng cách tới t ít hơn 1\n    cout << -1 << \"\\n\";\n    return 0;\n}",perf:{gen:n=>{const r=[];for(let i=n-1;i>=1;i--)r.push((i+1)+" "+i);for(let i=1;i+2<=n;i+=2)r.push(i+" "+(i+2));return n+" "+r.length+"\n"+r.join("\n")+"\n1 "+n},ns:[250,500,1000,2000],need:"n",limit:n=>120*n+300,why:"Cập nhật khoảng cách lặp lại trên mọi cạnh tới khi ổn định tốn O(n·m)."},py:{start:"from collections import deque\n\nn, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]\nfor _ in range(m):\n    u, v = map(int, input().split())\n    adj[u].append(v)\n    adj[v].append(u)\ns, t = map(int, input().split())\n# BFS từ t; rồi đi từ s, mỗi bước sang đỉnh kề NHỎ NHẤT có khoảng cách tới t ít hơn 1\nprint(-1)",hints:["Truy vết bằng mảng cha từ s chỉ cho một đường bất kỳ. Muốn nhỏ nhất theo thứ tự từ điển phải chọn tốt từ đỉnh ĐẦU (ý của bài 50).","BFS từ t để có d[v] = khoảng cách từ v tới t. Từ s, đỉnh v kề u nằm trên một đường ngắn nhất khi d[v] = d[u] − 1.","Mỗi bước chọn v nhỏ nhất thỏa điều kiện. Tổng chi phí vẫn O(n + m)."]},cs:{start:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        var adj = new List<int>[n + 1];\n        for (int u = 0; u <= n; u++) adj[u] = new List<int>();\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(e[1]);\n            adj[e[1]].Add(e[0]);\n        }\n        int[] st = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int s = st[0], t = st[1];\n        // BFS từ t; rồi đi từ s, mỗi bước sang đỉnh kề NHỎ NHẤT có khoảng cách tới t ít hơn 1\n        Console.WriteLine(-1);\n    }\n}",hints:["Truy vết bằng mảng cha từ s chỉ cho một đường bất kỳ. Muốn nhỏ nhất theo thứ tự từ điển phải chọn tốt từ đỉnh ĐẦU (ý của bài 50).","BFS từ t để có d[v] = khoảng cách từ v tới t. Từ s, đỉnh v kề u nằm trên một đường ngắn nhất khi d[v] = d[u] − 1.","Mỗi bước chọn v nhỏ nhất thỏa điều kiện. Tổng chi phí vẫn O(n + m)."]}}]);

